{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/cart-list.json
    The lines of a cart as a table or as cards: product, variant, price, quantity, line total and a remove button. Axes: layout (table, cards), media (image, none), density, tone.
    Props (p): id, title, lines, empty, labels, layout, media, tone, density, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_lines = ($p['lines'] ?? null)}
{var $v_empty = ($p['empty'] ?? '')}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'table')}
{var $v_media = ($p['media'] ?? 'image')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_density = ($p['density'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_10}
  {if og_t(og_eq(og_len($v_lines), 0))}
    {=og_include('blocks/empty-state.latte', ['p' => ['icon' => 'shopping-cart', 'title' => $v_empty]])|noescape}
  {elseif og_t(og_eq($v_layout, 'table'))}
    {=og_include('blocks/cart-table.latte', ['p' => ['field' => og_tpl('{0}-qty', [$v_id]), 'lines' => $v_lines, 'labels' => $v_labels, 'media' => $v_media, 'density' => $v_density]])|noescape}
  {else}
    {capture $c_9}
      {foreach og_l($v_lines) as $v_line}
        {capture $c_8}
          {capture $c_7}
            {if og_t(og_eq($v_media, 'image'))}
              {=og_include('blocks/media-frame.latte', ['p' => ['alt' => og_get($v_line, ['name']), 'ratio' => '1/1', 'className' => og_cnv(['size-16 shrink-0'])]])|noescape}
            {/if}
            {capture $c_4}
              {capture $c_1}
                {=og_text(og_get($v_line, ['name']))}
              {/capture}
              {=og_include('compose/Text.latte', ['size' => 'sm', 'weight' => 'semibold', 'children' => (string) $c_1])|noescape}
              {capture $c_2}
                {=og_text(og_get($v_line, ['variant']))}
              {/capture}
              {=og_include('compose/Text.latte', ['size' => 'xs', 'class' => 'text-muted-foreground', 'children' => (string) $c_2])|noescape}
              {capture $c_3}
                {=og_text(og_money(og_get($v_line, ['price']), og_get($v_line, ['currency'])))}
              {/capture}
              {=og_include('compose/Text.latte', ['size' => 'sm', 'children' => (string) $c_3])|noescape}
            {/capture}
            {=og_include('compose/Stack.latte', ['gap' => '0', 'class' => 'min-w-40 flex-1', 'children' => (string) $c_4])|noescape}
            {=og_include('blocks/number-field.latte', ['p' => ['value' => og_str(og_get($v_line, ['qty'])), 'name' => og_tpl('{0}-qty-{1}', [$v_id, og_get($v_line, ['id'])]), 'min' => '1', 'label' => og_get($v_labels, ['qty']), 'decrease' => og_get($v_labels, ['decrease']), 'increase' => og_get($v_labels, ['increase'])]])|noescape}
            {capture $c_5}
              {=og_text(og_money(og_mul(og_get($v_line, ['price']), og_get($v_line, ['qty'])), og_get($v_line, ['currency'])))}
            {/capture}
            {=og_include('compose/Text.latte', ['size' => 'base', 'weight' => 'bold', 'children' => (string) $c_5])|noescape}
            {capture $c_6}
              {=og_include('icons/LucideIcon.latte', ['name' => 'x', 'size' => 16])|noescape}
            {/capture}
            {=og_include('compose/Button.latte', ['variant' => 'ghost', 'size' => 'sm', 'layout' => 'icon', 'ariaLabel' => og_s(og_get($v_labels, ['remove'])), 'children' => (string) $c_6])|noescape}
          {/capture}
          {=og_include('compose/CardContent.latte', ['class' => 'flex flex-wrap items-center gap-4', 'children' => (string) $c_7])|noescape}
        {/capture}
        {=og_include('compose/Card.latte', ['variant' => 'default', 'children' => (string) $c_8])|noescape}
      {/foreach}
    {/capture}
    {=og_include('compose/Stack.latte', ['gap' => '4', 'align' => 'stretch', 'attrs' => og_attrs(['data-slot', 'cart-cards']), 'children' => (string) $c_9])|noescape}
  {/if}
{/capture}
{=og_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'tone' => $v_tone, 'density' => $v_density, 'landmarkLabel' => $v_landmarkLabel], 'children' => og_markup($c_10)])|noescape}
